        assert!(check_auth_strength(&crate::oauth::AuthStrength::Passkey, RiskTier::Tier3).is_ok());
        assert!(check_auth_strength(&crate::oauth::AuthStrength::Mfa, RiskTier::Tier3).is_ok());
