        assert!(check_auth_strength(&crate::oauth::AuthStrength::Passkey, RiskTier::Tier2).is_ok());
        assert!(check_auth_strength(&crate::oauth::AuthStrength::Mfa, RiskTier::Tier2).is_ok());
