            },
        ];
        assert!(find_jwk(&keys, &Some("key-1".to_string())).is_some());
        assert!(find_jwk(&keys, &Some("key-2".to_string())).is_some());
        assert!(find_jwk(&keys, &Some("key-3".to_string())).is_none());
    }

