    if jwks.keys.is_empty() {
        return Err(TokenError::InvalidToken(
            "JWKS contains no keys".to_string(),
        ));
    }

    // Update cache.
    *self.jwks_cache.lock().await = Some(CachedJwks {
        keys: jwks.keys.clone(),
        fetched_at: Instant::now(),
    });

    Ok(jwks)
}

