   151	fn rpc_request(
   152	    host: &str,
   153	    token: Option<&str>,
   154	    session: Option<&str>,
   155	    method: &str,
   156	) -> Request<Body> {
   157	    let params = if method == "initialize" {
   158	        serde_json::json!({"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"host-regression","version":"1"}})
   159	    } else if method == "tools/call" {
   160	        serde_json::json!({"name":"calendar_list","arguments":{}})
   161	    } else {
   162	        serde_json::json!({})
   163	    };
   164	    let mut builder = Request::builder()
   165	        .method("POST")
   166	        .uri("/mcp")
   167	        .header("host", host)
   168	        .header("content-type", "application/json")
   169	        .header("accept", "application/json, text/event-stream");
   170	    if let Some(token) = token {
   171	        builder = builder.header("authorization", format!("Bearer {token}"));
   172	    }
   173	    if let Some(session) = session {
   174	        builder = builder
   175	            .header("mcp-session-id", session)
   176	            .header("mcp-protocol-version", "2025-03-26");
   177	    }
   178	    let mut message = serde_json::json!({"jsonrpc":"2.0","method":method,"params":params});
   179	    if !method.starts_with("notifications/") {
   180	        message["id"] = serde_json::json!(1);
   181	    }
   182	    builder.body(Body::from(message.to_string())).unwrap()
   183	}
