   257	async fn decoded_result(response: axum::response::Response) -> serde_json::Value {
   258	    use http_body_util::BodyExt;
   259	    let body = response.into_body().collect().await.unwrap().to_bytes();
   260	    let text = std::str::from_utf8(&body).unwrap();
   261	    let payload = text
   262	        .lines()
   263	        .filter_map(|line| line.strip_prefix("data:").map(str::trim))
   264	        .find(|data| !data.is_empty())
   265	        .unwrap_or(text);
   266	    let message: serde_json::Value = serde_json::from_str(payload).unwrap();
   267	    assert_eq!(message["jsonrpc"], "2.0");
   268	    assert_eq!(message["id"], 1);
   269	    assert!(message.get("error").is_none());
   270	    message
   271	        .get("result")
   272	        .expect("successful JSON-RPC result")
   273	        .clone()
   274	}
